# excel-to-sigma linked input table - call 2 of 3: linked input table + columns
# target: existing workbook (the id call 1 returned)
data_page = sigma.workbook.get_page('<DATA PAGE ID>')
page = sigma.workbook.get_page('<PAGE ID>')
if not (isinstance(data_page, Page) and isinstance(page, Page)):
    raise RuntimeError('re-fetch pages')
plan_base = data_page.get_element('<PLAN BASE ID>')
if not isinstance(plan_base, LevelTable):
    raise RuntimeError('re-fetch grouped table')
lt = page.add_linked_input_table(plan_base.to_source(), lookup_columns={'Line Item': 'Line Item'}, source_columns={'Baseline Rate': 'Baseline Rate'})
lt.set_name('Rate overrides')
lt.set_edit_mode('published-all-users')
lt.set_frame(1, 3, 24, 16)
k0 = lt.get_column_by_name('Line Item')
i0 = lt.get_column_by_name('Baseline Rate')
e0 = lt.add_editable_column('Override Rate', 'number')
e1 = lt.add_editable_column('Rationale', 'text')
f0 = lt.add_formula_column('Effective Rate', sigma.formula.coalesce(e0, i0))
pk = lt.list_primary_key_columns()
print('primaryKeyColumns=' + str(len(pk)))
print('linkedTableId=' + lt.id())
print('column:Line Item=' + k0.id())
print('column:Baseline Rate=' + i0.id())
print('column:Override Rate=' + e0.id())
print('column:Rationale=' + e1.id())
print('column:Effective Rate=' + f0.id())
